import type { TermInput } from "@/lib/schema";

/**
 * Trial designs, statistics and the trial lifecycle, at depth (roadmap row 136). Every design is a term with a worked
 * example from a trial in the corpus, the phrases patients meet as aliases, and a primer or guideline link.
 * Existing terms (randomised-trial, non-inferiority, single-arm, basket-umbrella-platform, seamless-adaptive,
 * dose-escalation-design, crossover, hazard-ratio, the endpoint terms) are enriched in place in their own files;
 * this file adds only what was missing. The design picker page at /trial-designs/ reads these ids.
 * Chinese TL;DRs are exported as `tldrZh` for the i18n owner to merge into src/data/i18n/zh.ts.
 */
const asOf = "2026-09-17";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const ICH_E9 = { label: "ICH E9 and E9(R1): statistical principles for clinical trials and the estimand framework", url: "https://www.ich.org/page/efficacy-guidelines" };
const CONSORT = { label: "CONSORT statement: reporting randomised trials", url: "https://www.consort-statement.org/" };
const FDA_GUIDANCE = "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/";
type L = { label: string; url: string };
type T = Omit<TermInput, "kind" | "asOf" | "links"> & { wikipedia?: string; links?: L[] };
const t = (x: T): TermInput => {
  const links: L[] = [...(x.wikipedia ? [{ label: "Wikipedia", url: x.wikipedia }] : []), ...(x.links ?? [])];
  return { kind: "term", asOf, sections: ["drug-discovery"], ...x, links: links.length ? links : undefined };
};

