    aka: ["trial failure", "failed trial", "failed trials", "negative trial", "negative trials", "why trials fail", "why the trial failed", "underpowered", "underpowered trial", "wrong endpoint", "wrong comparator", "control arm drift", "control arm underperformed", "control arm outperformed", "control arm did better than expected", "historical control comparison", "regression to the mean", "winner's curse", "subgroup fishing", "cherry-picked subgroup", "post-hoc subgroup", "crossover contamination", "contamination", "diluted effect", "treatment dilution", "non-adherence", "poor adherence", "dropout", "loss to follow-up", "lost to follow-up", "immature data", "did not replicate", "failed to replicate", "phase 2 signal did not hold", "informative censoring", "technically negative"],
